def logistic_map(width, height, x_coords, y_coords):
    if not x_coords or not y_coords:
        return [[None for _ in range(width)] for _ in range(height)]

    result = []
    for r in range(height):
        row = []
        for c in range(width):
            min_dist = float('inf')
            for sx, sy in zip(x_coords, y_coords):
                dist = abs(c - sx) + abs(r - sy)
                if dist < min_dist:
                    min_dist = dist
            row.append(min_dist)
        result.append(row)

    return result
